import pandas as pd, numpy as np
from scipy import stats
for i in [1,3,4,5,6]:
    df=pd.read_csv(eval(f"experiment_{i}_csv"))
    print(f"exp{i}",df.shape[1],"cols",list(df.columns))
    if 'RackInletTemp' in df and 'JobThroughput' in df:
        r,p=stats.pearsonr(df.RackInletTemp,df.JobThroughput)
        print(f"  inlet-TP r={r:.3f} p={p:.1e}")
    if 'do_cooling_setpoint_controller' in df:
        print("  setpoint vals:",df.do_cooling_setpoint_controller.unique()[:5], "TP mean",df.JobThroughput.mean())

